  "leaf_target_rings": "\n    <svg class=\"symptom-svg\" viewBox=\"0 0 160 120\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"Concentric target rings leaf spot symptom\">\n      <rect width=\"160\" height=\"120\" fill=\"#F4EFE6\" rx=\"8\"/>\n      <path d=\"M 30 100 C 20 50, 60 20, 135 25 C 145 75, 100 105, 30 100 Z\" fill=\"#588B66\" stroke=\"#1F4D3A\" stroke-width=\"2\"/>\n      <path d=\"M 30 100 Q 80 60 135 25\" stroke=\"#1F4D3A\" stroke-width=\"1.8\" fill=\"none\"/>\n      <!-- Concentric spot 1 -->\n      <ellipse cx=\"85\" cy=\"55\" rx=\"22\" ry=\"16\" fill=\"#F2DFB8\" stroke=\"#E8A317\" stroke-width=\"1.5\"/>\n      <ellipse cx=\"85\" cy=\"55\" rx=\"16\" ry=\"11\" fill=\"#7A4B26\" stroke=\"#4A2E16\" stroke-width=\"1.5\"/>\n      <ellipse cx=\"85\" cy=\"55\" rx=\"10\" ry=\"7\" fill=\"#4A2E16\" stroke=\"#301E0E\" stroke-width=\"1.5\"/>\n      <circle cx=\"85\" cy=\"55\" r=\"3.5\" fill=\"#1F1309\"/>\n      <!-- Concentric spot 2 -->\n      <ellipse cx=\"52\" cy=\"78\" rx=\"14\" ry=\"10\" fill=\"#F2DFB8\" stroke=\"#E8A317\" stroke-width=\"1.2\"/>\n      <ellipse cx=\"52\" cy=\"78\" rx=\"9\" ry=\"6\" fill=\"#7A4B26\" stroke=\"#4A2E16\" stroke-width=\"1.2\"/>\n      <circle cx=\"52\" cy=\"78\" r=\"3\" fill=\"#301E0E\"/>\n      <text x=\"80\" y=\"112\" text-anchor=\"middle\" font-family=\"'DM Sans', sans-serif\" font-weight=\"600\" font-size=\"9\" fill=\"#1F4D3A\">Concentric Bullseye Rings</text>\n    </svg>\n  ",
  "rice_blast_spindle": "\n    <svg class=\"symptom-svg\" viewBox=\"0 0 160 120\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"Rice blast diamond spindle shaped leaf lesions\">\n      <rect width=\"160\" height=\"120\" fill=\"#F4EFE6\" rx=\"8\"/>\n      <!-- Slender rice leaf blade -->\n      <path d=\"M 18 95 C 45 60, 95 30, 142 18 C 128 55, 78 88, 18 95 Z\" fill=\"#5A8F6A\" stroke=\"#1F4D3A\" stroke-width=\"2\"/>\n      <path d=\"M 18 95 Q 85 54 142 18\" stroke=\"#1F4D3A\" stroke-width=\"1.6\" fill=\"none\"/>\n      <!-- Spindle 1 (eye shaped with grey center & brown border) -->\n      <path d=\"M 60 70 Q 75 56 95 62 Q 78 78 60 70 Z\" fill=\"#7A3F18\" stroke=\"#B85D19\" stroke-width=\"1.5\"/>\n      <path d=\"M 67 68 Q 76 61 88 64 Q 78 73 67 68 Z\" fill=\"#CFD5D0\"/>\n      <!-- Spindle 2 -->\n      <path d=\"M 92 48 Q 106 36 122 42 Q 108 55 92 48 Z\" fill=\"#7A3F18\" stroke=\"#B85D19\" stroke-width=\"1.5\"/>\n      <path d=\"M 98 46 Q 106 40 115 43 Q 107 51 98 46 Z\" fill=\"#CFD5D0\"/>\n      <text x=\"80\" y=\"112\" text-anchor=\"middle\" font-family=\"'DM Sans', sans-serif\" font-weight=\"600\" font-size=\"9\" fill=\"#1F4D3A\">Spindle / Eye-Shaped Blast</text>\n    </svg>\n  ",
  "leaf_water_soaked_blight": "\n    <svg class=\"symptom-svg\" viewBox=\"0 0 160 120\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"Water soaked dark lesions with white mold late blight symptom\">\n      <rect width=\"160\" height=\"120\" fill=\"#F4EFE6\" rx=\"8\"/>\n      <path d=\"M 28 98 C 22 45, 68 18, 138 22 C 142 75, 95 105, 28 98 Z\" fill=\"#4F7A5D\" stroke=\"#1F4D3A\" stroke-width=\"2\"/>\n      <path d=\"M 28 98 Q 80 58 138 22\" stroke=\"#1F4D3A\" stroke-width=\"1.8\" fill=\"none\"/>\n      <!-- Dark water-soaked lesion -->\n      <path d=\"M 65 35 C 95 30, 115 50, 105 75 C 80 85, 55 70, 65 35 Z\" fill=\"#283A2E\" stroke=\"#16231B\" stroke-width=\"1.5\"/>\n      <!-- White downy mold halo -->\n      <path d=\"M 63 32 Q 95 26 112 48 Q 112 78 102 82 Q 76 90 52 68 Q 50 45 63 32 Z\" stroke=\"#FFFFFF\" stroke-width=\"2.5\" stroke-dasharray=\"3,2\" fill=\"none\"/>\n      <text x=\"80\" y=\"112\" text-anchor=\"middle\" font-family=\"'DM Sans', sans-serif\" font-weight=\"600\" font-size=\"9\" fill=\"#1F4D3A\">Water-Soaked Blight + Mold</text>\n    </svg>\n  ",
  "rice_bacterial_blight": "\n    <svg class=\"symptom-svg\" viewBox=\"0 0 160 120\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-label=\"Bacterial leaf blight wavy translucent drying margin\">\n      <rect width=\"160\" height=\"120\" fill=\"#F4EFE6\" rx=\"8\"/>\n      <path d=\"M 22 98 C 35 45, 80 20, 138 20 C 130 50, 95 85, 22 98 Z\" fill=\"#588C67\" stroke=\"#1F4D3A\" stroke-width=\"2\"/>\n      <path d=\"M 22 98 Q 80 55 138 20\" stroke=\"#1F4D3A\" stroke-width=\"1.8\" fill=\"none\"/>\n      <!-- Wavy dried bleached straw margin -->\n      <path d=\"M 138 20 C 120 28, 105 25, 95 40 C 85 52, 70 65, 45 80 L 22 98 C 50 102, 95 90, 138 20 Z\" fill=\"#E8C882\" stroke=\"#B89445\" stroke-width=\"1.5\"/>\n      <!-- Amber bacterial ooze droplets -->\n      <circle cx=\"104\" cy=\"38\" r=\"5\" fill=\"#E8A317\" stroke=\"#9E6800\" stroke-width=\"1.2\"/>\n      <circle cx=\"102\" cy=\"36\" r=\"1.5\" fill=\"#FFFFFF\" opacity=\"0.8\"/>\n      <circle cx=\"75\" cy=\"62\" r=\"4\" fill=\"#E8A317\" stroke=\"#9E6800\" stroke-width=\"1\"/>\n      <text x=\"80\" y=\"112\" text-anchor=\"middle\" font-family=\"'DM Sans', sans-serif\" font-weight=\"600\" font-size=\"9\" fill=\"#1F4D3A\">Wavy Bleached Margins + Ooze</text>\n    </svg>\n  ",
